goal_id = ? OR s.governing_goal_id = ?))\n     ORDER BY s.session_key`, ws, since, g.id, g.id);\n        // A session's latest time on this goal: its newest usage in an epoch bound to the goal, or the newest such epoch's start.\n        const lastOf = (key) => latest(get(\"SELECT MAX(u.ts) AS t FROM v2_usage u JOIN v2_epochs e ON e.ws_id = u.ws_id AND e.session_key = u.session_key AND e.epoch_id = u.epoch_id WHERE u.ws_id = ? AND u.session_key = ? AND e.goal_id = ?\", ws, key, g.id)?.t, get(\"SELECT MAX(starts_at) AS t FROM v2_epochs WHERE ws_id = ? AND session_key = ? AND goal_id = ?\", ws, key, g.id)?.t);\n        const by_harness = { \"claude-code\": 0, codex: 0 };\n        let active_now = 0;\n        const mine = [];\n        const cutoff = new (readDate())(now - ACTIVE_MS).toISOString();\n        for (const s of lines) {\n            by_harness[s.harness]++;\n            const last = lastOf(s.session_key);\n            const onGoalNow = s.open_goal === g.id || s.governing_goal_id === g.id;\n            if (s.state === \"shared\" && !s.agent_stopped && onGoalNow && !!last && last >= cutoff)\n                active_now++;\n            if (s.user_id === pp.userId)\n                mine.push({ session_key: s.session_key, harness: s.harness, state: s.state, last_activity_at: last });\n        }\n        const last_activity_at = latest(get(\"SELECT MAX(u.ts) AS t FROM v2_usage u JOIN v2_epochs e ON e.ws_id = u.ws_id AND e.session_key = u.session_key AND e.epoch_id = u.epoch_id WHERE u.ws_id = ? AND e.goal_id = ?\", ws, g.id)?.t, get(\"SELECT MAX(starts_at) AS t FROM v2_epochs WHERE ws_id = ? AND goal_id = ?\", ws, g.id)?.t, get(\"SELECT MAX(at) AS t FROM v2_activity WHERE ws_id = ? AND goal_id = ?\", ws, g.id)?.t);\n        let detail = null;\n        if (seesActivityDetail(pp, g)) {\n            const live = nowIso();\n            const files = all(\"SELECT path FROM v2_activity WHERE ws_id = ? AND goal_id = ? AND expires_at > ? AND path IS NOT NULL GROUP BY path O